import{_ as r,o as a,c as d,a3 as e}from"./chunks/framework.Bh_aNVBG.js";const c=JSON.parse('{"title":"1. 서비스 개요","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),o={name:"overview.md"};function i(l,t,n,p,s,h){return a(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="_1-서비스-개요" tabindex="-1">1. 서비스 개요 <a class="header-anchor" href="#_1-서비스-개요" aria-label="Permalink to &quot;1. 서비스 개요&quot;">​</a></h1><h2 id="_1-1-서비스-소개" tabindex="-1">1.1. 서비스 소개 <a class="header-anchor" href="#_1-1-서비스-소개" aria-label="Permalink to &quot;1.1. 서비스 소개&quot;">​</a></h2><p><strong>인포디오(Infodio)</strong> 는 축제 및 행사 운영자가 방문객을 위한 안내 페이지를 직접 제작하고 운영할 수 있도록 지원하는 플랫폼입니다.</p><p>콘텐츠 관리 시스템(CMS)을 통해 행사 정보, 프로그램 일정, 장소 안내, 지도, 스탬프 투어 등 다양한 서비스를 하나의 안내 페이지로 구성할 수 있습니다.</p><p>행사의 규모와 운영 목적에 따라 필요한 기능을 선택하여 사용할 수 있으며, 행사 운영 중에도 등록된 콘텐츠를 수정하고 관리할 수 있습니다.</p><p>이를 통해 행사 운영자는 방문객에게 필요한 정보를 효과적으로 제공하고, 방문객은 모바일 환경에서 행사 정보를 편리하게 확인할 수 있습니다.</p><h2 id="_1-2-주요-기능" tabindex="-1">1.2. 주요 기능 <a class="header-anchor" href="#_1-2-주요-기능" aria-label="Permalink to &quot;1.2. 주요 기능&quot;">​</a></h2><p>인포디오는 다음과 같은 주요 기능을 제공합니다.</p><table tabindex="0"><thead><tr><th>기능</th><th>설명</th></tr></thead><tbody><tr><td>프로젝트 관리</td><td>축제 및 행사별 프로젝트를 생성하고 기본 정보를 설정합니다.</td></tr><tr><td>홈 화면 관리</td><td>메인 배너, 바로가기 등 안내 페이지의 주요 화면을 구성합니다.</td></tr><tr><td>콘텐츠 관리</td><td>행사 소개 및 각종 안내 콘텐츠를 등록하고 관리합니다.</td></tr><tr><td>투어맵</td><td>행사장 내 시설, 부스, 주요 장소 등을 지도에 표시합니다.</td></tr><tr><td>일정 관리</td><td>공연, 체험 프로그램 등 행사 일정을 등록하고 안내합니다.</td></tr><tr><td>AI 챗봇</td><td>방문객이 행사 관련 정보를 대화형으로 확인할 수 있도록 지원합니다.</td></tr><tr><td>스탬프 투어</td><td>방문객 참여를 위한 스탬프 코스 및 보상을 관리합니다.</td></tr><tr><td>설문조사</td><td>방문객의 의견을 수집하기 위한 설문조사를 구성합니다.</td></tr><tr><td>오디오 가이드</td><td>음성을 활용한 행사 및 장소 안내 콘텐츠를 제공합니다.</td></tr><tr><td>비디오 가이드</td><td>영상을 활용한 안내 콘텐츠를 제공합니다.</td></tr><tr><td>공지사항</td><td>행사 운영과 관련된 주요 공지사항을 등록하고 관리합니다.</td></tr><tr><td>대시보드</td><td>방문객 현황과 서비스 이용 통계 등을 확인합니다.</td></tr></tbody></table><h2 id="_1-3-서비스-구성" tabindex="-1">1.3. 서비스 구성 <a class="header-anchor" href="#_1-3-서비스-구성" aria-label="Permalink to &quot;1.3. 서비스 구성&quot;">​</a></h2><p>인포디오는 <strong>CMS(관리자 페이지)</strong> 와 <strong>방문객용 안내 페이지</strong>로 구성됩니다.</p><h3 id="_1-cms-관리자-페이지" tabindex="-1">① CMS(관리자 페이지) <a class="header-anchor" href="#_1-cms-관리자-페이지" aria-label="Permalink to &quot;① CMS(관리자 페이지)&quot;">​</a></h3><p>행사 운영자가 프로젝트를 생성하고 안내 페이지를 구성·관리하는 공간입니다.</p><p>CMS에서는 다음과 같은 작업을 수행할 수 있습니다.</p><ul><li>프로젝트 생성 및 기본 정보 설정</li><li>안내 페이지 디자인 및 메뉴 구성</li><li>행사 콘텐츠 및 일정 등록</li><li>지도 및 주요 장소 정보 관리</li><li>스탬프 투어 설정</li><li>공지사항 등록 및 수정</li><li>방문객 이용 현황 및 통계 확인</li></ul><h3 id="_2-방문객용-안내-페이지" tabindex="-1">② 방문객용 안내 페이지 <a class="header-anchor" href="#_2-방문객용-안내-페이지" aria-label="Permalink to &quot;② 방문객용 안내 페이지&quot;">​</a></h3><p>CMS에서 등록한 콘텐츠와 설정을 바탕으로 방문객에게 제공되는 모바일 중심의 웹페이지입니다.</p><p>방문객은 별도의 앱 설치 없이 웹 브라우저를 통해 행사 정보를 확인할 수 있습니다.</p><p>방문객용 안내 페이지에서는 프로젝트에 설정된 기능에 따라 행사 일정 확인, 장소 검색, 지도 탐색, 스탬프 투어 참여 등의 서비스를 이용할 수 있습니다.</p><h2 id="_1-4-서비스-이용-절차" tabindex="-1">1.4. 서비스 이용 절차 <a class="header-anchor" href="#_1-4-서비스-이용-절차" aria-label="Permalink to &quot;1.4. 서비스 이용 절차&quot;">​</a></h2><p>인포디오의 기본적인 이용 절차는 다음과 같습니다.</p><p><strong>STEP 1. 프로젝트 생성</strong></p><p>축제 또는 행사에 대한 기본 정보를 입력하고 새로운 프로젝트를 생성합니다.</p><p><strong>STEP 2. 서비스 기능 선택</strong></p><p>홈, 투어맵, 일정, AI 챗봇, 스탬프 투어 등 행사에 필요한 기능을 선택합니다.</p><p><strong>STEP 3. 안내 페이지 구성</strong></p><p>프로젝트의 테마, 메인 배너, 바로가기, 메뉴 등을 설정하여 안내 페이지를 구성합니다.</p><p><strong>STEP 4. 콘텐츠 등록</strong></p><p>행사 일정, 장소 정보, 상세 콘텐츠, 공지사항 등 방문객에게 제공할 정보를 등록합니다.</p><p><strong>STEP 5. 안내 페이지 확인 및 운영</strong></p><p>설정한 내용을 확인한 후 방문객에게 안내 페이지를 제공하고, 행사 운영 중 필요한 정보를 수정·관리합니다.</p><p><strong>STEP 6. 운영 현황 확인</strong></p><p>대시보드를 통해 방문객 접속 현황 및 주요 서비스 이용 통계를 확인합니다.</p><h2 id="_1-5-사용자-매뉴얼-안내" tabindex="-1">1.5. 사용자 매뉴얼 안내 <a class="header-anchor" href="#_1-5-사용자-매뉴얼-안내" aria-label="Permalink to &quot;1.5. 사용자 매뉴얼 안내&quot;">​</a></h2><p>본 매뉴얼은 인포디오 CMS를 이용하여 축제 및 행사 안내 페이지를 직접 제작하고 운영하는 사용자를 대상으로 작성되었습니다.</p><p>프로젝트 생성부터 콘텐츠 등록, 서비스 설정, 운영 현황 확인까지 주요 기능의 사용 방법을 단계별로 안내합니다.</p><p>각 기능별 설명은 다음과 같이 구성됩니다.</p><ul><li><strong>기능 소개:</strong> 해당 기능의 용도와 활용 방법</li><li><strong>설정 방법:</strong> CMS에서 기능을 설정하는 단계별 절차</li><li><strong>화면 안내:</strong> 주요 화면 및 입력 항목에 대한 설명</li><li><strong>참고 및 주의사항:</strong> 기능 사용 시 알아두어야 할 사항</li></ul><p>※ 본 매뉴얼의 화면 구성 및 기능은 서비스 업데이트에 따라 일부 변경될 수 있습니다.</p>',39)])])}const g=r(o,[["render",i]]);export{c as __pageData,g as default};
